lines = []
with open('deploy.log') as f:
    all_lines = f.read().split('\n')
header = all_lines[0]
errors = [l for l in all_lines if l.startswith('ERROR')]
strs = [header] + errors
for s in strs:
    print(repr(s), len(s))

def overlap(a,b):
    # max k such that suffix of a (len k) == prefix of b (len k)
    best=0
    for k in range(1, min(len(a),len(b))+1):
        if a[-k:]==b[:k]:
            best=k
    return best

for i,a in enumerate(strs):
    for j,b in enumerate(strs):
        if i!=j:
            print(i,j,overlap(a,b))
